-- ── the trap, written on the rows themselves ────────────────────────────────
UPDATE reg_products SET
  notes = TRIM(COALESCE(notes,'') || CASE WHEN COALESCE(notes,'')='' THEN '' ELSE ' | ' END ||
    'ยังไม่มีเลขสารบบอาหาร · หมายเหตุ 15/08/26: เลขสารบบ 0025 ถึง 0038 ถูกออกให้ผลิตภัณฑ์อื่นไปแล้ว ไม่ใช่รายการนี้ อย่าอนุมานว่ารหัสแถว RP00xx ตรงกับเลขสารบบ -00xx เพราะความสอดคล้องนั้นสิ้นสุดที่ RP0024 · เมื่อได้เลขจริงให้กรอกลงช่องเลขสารบบและเปลี่ยนสถานะเป็นขึ้นทะเบียนแล้ว'),
  modified = strftime('%Y-%m-%dT%H:%M:%fZ','now')
WHERE id IN ('RP0025','RP0026','RP0027','RP0028','RP0029','RP0030','RP0031');

-- ลูกชิ้นและไส้กรอก are the two groups QM-QA-04 ข้อ 1 excludes by name. Their
-- rows should say so, because the register is where someone checks before
-- starting a production run.
UPDATE reg_products SET
  notes = TRIM(COALESCE(notes,'') || ' | ' ||
    '⚠️ กลุ่มผลิตภัณฑ์นี้อยู่นอกขอบเขตการวิเคราะห์อันตรายที่อนุมัติ — QM-QA-04 ข้อ 1 ระบุว่ากลุ่มลูกชิ้นและไส้กรอกใช้กระบวนการผลิตต่างจากกลุ่มเสียบไม้ ต้องจัดทำการวิเคราะห์อันตรายแยกฉบับก่อนเริ่มผลิตเชิงพาณิชย์ · ห้ามเริ่มผลิตเพียงเพราะได้เลขสารบบแล้ว — เลขสารบบกับขอบเขต HACCP เป็นคนละเรื่องกัน'),
  modified = strftime('%Y-%m-%dT%H:%M:%fZ','now')
WHERE id IN ('RP0025','RP0026','RP0027','RP0028');

-- ── the label artwork under review ──────────────────────────────────────────
-- The declared recipe on the RP0004 artwork is recorded as printed, because
-- that is what the register is for. It does not add up, and the note says so
-- rather than quietly correcting a number nobody has authorised changing.
UPDATE reg_products SET
  composition = '[{"name":"เนื้อหมู","percent":42},{"name":"มันสัน","percent":27},{"name":"เนื้อไก่","percent":15},{"name":"น้ำตาล","percent":12},{"name":"เครื่องปรุงรสอื่น","percent":5},{"name":"ผลิตภัณฑ์นม","percent":1},{"name":"เกลือบริโภคเสริมไอโอดีน","percent":0.5},{"name":"เครื่องเทศ","percent":0.3}]',
  compositionNote = 'บันทึกตามที่ปรากฏบนอาร์ตเวิร์กฉลากฉบับทบทวน 15/08/26 ยังไม่แก้ตัวเลขให้ เพราะการแก้สูตรต้องมาจากผู้มีอำนาจ

⚠️ ผลรวมได้ 102.8% ซึ่งเกิน 100% — 42+27+15+12+5+1+0.5+0.3 · ต้องแก้ก่อนทำเพลทพิมพ์
⚠️ "เครื่องปรุงรสอื่น" อยู่ที่ 5% พอดี ซึ่งถึงเกณฑ์ที่ต้องแจกแจงส่วนประกอบย่อย และเป็นตัวที่นำสารก่อภูมิแพ้ 3 จาก 4 ชนิดเข้ามา (ข้าวสาลี ถั่วเหลือง หอย) ควรระบุเป็น "เครื่องปรุงรสอื่น (มีข้าวสาลี ถั่วเหลือง หอย)"
ลำดับส่วนประกอบเรียงจากมากไปน้อยถูกต้องแล้ว',
  notes = TRIM(COALESCE(notes,'') || CASE WHEN COALESCE(notes,'')='' THEN '' ELSE ' | ' END ||
    'ทบทวนอาร์ตเวิร์กฉลาก 15/08/26 — พบข้อบกพร่อง 6 จุด ดู NCR-256908-015 · ยังไม่อนุมัติให้ทำเพลท'),
  modified = strftime('%Y-%m-%dT%H:%M:%fZ','now')
WHERE id = 'RP0004';

-- ── findings ────────────────────────────────────────────────────────────────
INSERT OR IGNORE INTO nc_capa
  (id, date, type, description, severity, source, owner, status, notes, created, modified)
VALUES
  ('NCR-256908-014','2026-08-15','Audit',
   'ทะเบียนผลิตภัณฑ์ที่ขึ้นทะเบียน อย. แล้วมี 38 รายการ แต่การวิเคราะห์อันตรายที่อนุมัติครอบคลุมผลิตภัณฑ์ตัวแทนเพียงตัวเดียว และไม่มีเอกสารแสดงว่าผลิตภัณฑ์ใดอยู่ในกลุ่มใด
· QM-QA-04 ข้อ 1 ระบุขอบเขตเป็น "กลุ่มผลิตภัณฑ์เนื้อสัตว์หมักเสียบไม้แช่เยือกแข็ง ซึ่งใช้กระบวนการผลิตร่วมกัน" โดยมีหมูปิ้งนมสดเป็นผลิตภัณฑ์ตัวแทน แต่ไม่มีบัญชีระบุว่าผลิตภัณฑ์ที่ขึ้นทะเบียนแล้ว 38 รายการ รายการใดบ้างที่ตัวแทนนี้ครอบคลุม
· ประเด็นที่ต้องพิจารณาเป็นลำดับแรก:
(1) มีผลิตภัณฑ์เนื้อไก่ 9 รายการ (เลขสารบบ 0021 – 0032 หลายรายการ) ขณะที่ผลิตภัณฑ์ตัวแทนเป็นหมูผสมไก่ 15% · สัตว์ปีกมีความชุกของ Salmonella และ Campylobacter สูงกว่าสุกร การใช้ผลิตภัณฑ์ตัวแทนที่เป็นหมูเป็นหลักจึงต้องมีเหตุผลรองรับ
(2) เลขสารบบ 0032 ชื่อ "โครงไก่หมักซอสแดงสูตรโบราณ" (Chicken Carcass) อาจไม่ผ่านขั้นตอนเสียบไม้ ซึ่งเป็นขั้นตอนที่ 12 ของแผนภูมิที่อนุมัติ ถ้าไม่ผ่านจริง ลำดับกระบวนการต่างจากแผนภูมิ และต้องพิจารณาว่าอยู่นอกขอบเขตหรือไม่
(3) เลขสารบบ 0035 "หมูหมักงา" มีงาเป็นส่วนประกอบ — งาเป็นสารก่อภูมิแพ้ที่ยังไม่ปรากฏในรายการสารก่อภูมิแพ้ของโรงงาน (QM-QA-09 ข้อ 3 ระบุไว้ 4 กลุ่ม คือ ถั่วเหลือง ข้าวสาลี นม หอย)
(4) แบรนด์ หมูหอมซีเลคชั่น มีผลิตภัณฑ์ที่ขึ้นทะเบียนแล้ว 6 รายการ (0031, 0034 – 0038) ซึ่งเป็นแบรนด์ที่ยังไม่เคยปรากฏในเอกสารระบบ HACCP
· ตามหลักการจัดกลุ่มผลิตภัณฑ์ ต้องมีเอกสารแสดงเหตุผลว่าผลิตภัณฑ์ตัวแทนครอบคลุมผลิตภัณฑ์ใดบ้าง โดยพิจารณาจากวัตถุดิบ สารก่อภูมิแพ้ วัตถุเจือปน และลำดับกระบวนการที่เหมือนหรือต่างกัน',
   'Major','รายการใบสำคัญ อย. 0021 – 0038 เทียบกับ QM-QA-04 ข้อ 1 — ทวนสอบ 15/08/26',
   'QA / คณะทำงาน HACCP','Open',
   'การมีเลขสารบบอาหารไม่ได้แปลว่าผลิตภัณฑ์อยู่ในขอบเขตแผน HACCP — เป็นคนละระบบกำกับกัน ผู้ตรวจรับรอง GHPs/HACCP ถามหาเอกสารจัดกลุ่มผลิตภัณฑ์ ไม่ใช่ใบสำคัญ อย.
· ทางแก้ที่เร็วที่สุดคือทำตารางจัดกลุ่มผลิตภัณฑ์แผ่นเดียว ระบุทุกเลขสารบบว่าอยู่กลุ่มใด ใช้การวิเคราะห์อันตรายฉบับใด และต่างจากผลิตภัณฑ์ตัวแทนตรงไหน (วัตถุดิบ/สารก่อภูมิแพ้/วัตถุเจือปน/ลำดับขั้นตอน) — ทำได้ก่อนการตรวจกลางกันยายน
· รายการที่ต่างจากตัวแทนมากที่สุดควรวิเคราะห์แยก ไม่ใช่รวมเข้ากลุ่มเพื่อความสะดวก',
